    "UZ": "Texnologiya xaridorga mahsulotni yaxshiroq tushunishga yordam berishi kerak. MIRROR do‘kon tajribasini murakkablashtirmasdan, ko‘rish va tanlash jarayonini soddalashtirishga qaratilgan.",
    "RU": "Технологии должны помогать понять товар. MIRROR упрощает просмотр и выбор, не усложняя посещение магазина.",
    "KK": "Технология өнімді түсінуге көмектесуі тиіс. MIRROR дүкен тәжірибесін қиындатпай қарап таңдауды жеңілдетеді.",
