    "UZ": "Brend, do‘kon tarmog‘i yoki texnologik hamkorlik bo‘yicha g‘oyangizni yuboring. Kerakli ma’lumotlarni ko‘rib chiqib, keyingi qadamlarni birga belgilaymiz.",
    "RU": "Поделитесь идеями сотрудничества для бренда, сети или технологий. Рассмотрим информацию и согласуем следующие шаги.",
