    "RU": "Поделитесь идеями сотрудничества для бренда, сети или технологий. Рассмотрим информацию и согласуем следующие шаги.",
    "KK": "Бренд, дүкен желісі не технологиялық серіктестік идеяңызды жіберіңіз. Ақпаратты қарап, келесі қадамдарды бірге белгілейміз.",
